const std = @import("std");

/// Subcommands of `app`. Each one is an independent module rooted at
/// `src/<name>/root.zig` that exposes `pub fn run(init: std.process.Init) !void`.
const subcommands = [_][]const u8{ "wordfreq", "lru", "calc" };

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe_mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const test_step = b.step("test", "Run all unit tests");

    for (subcommands) |name| {
        const mod = b.createModule(.{
            .root_source_file = b.path(b.fmt("src/{s}/root.zig", .{name})),
            .target = target,
            .optimize = optimize,
        });
        exe_mod.addImport(name, mod);

        const run_tests = b.addRunArtifact(b.addTest(.{ .root_module = mod }));
        const step = b.step(b.fmt("test-{s}", .{name}), b.fmt("Run unit tests of the {s} subcommand", .{name}));
        step.dependOn(&run_tests.step);
        test_step.dependOn(&run_tests.step);
    }

    const exe = b.addExecutable(.{
        .name = "app",
        .root_module = exe_mod,
    });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the app (pass the subcommand after --)");
    run_step.dependOn(&run_cmd.step);

    const exe_tests = b.addRunArtifact(b.addTest(.{ .root_module = exe_mod }));
    test_step.dependOn(&exe_tests.step);
}

//! Evaluates one line of the calc grammar (see the "calc" section of SPEC.md)
//! over signed 64-bit integers.
//!
//! The parser is an operator-precedence (shunting-yard) machine with explicit
//! stacks rather than recursive descent, so arbitrarily deep nesting such as
//! `((((…))))` or `------1` is bounded by heap memory, not by the call stack.
//! The stacks are kept between calls so that evaluating many lines reuses
//! their capacity.

const std = @import("std");
const Allocator = std.mem.Allocator;

const Evaluator = @This();

gpa: Allocator,
values: std.ArrayList(i64) = .empty,
operators: std.ArrayList(Operator) = .empty,

pub const Error = error{
    /// The input does not match the grammar.
    Syntax,
    /// A `/` or `%` whose right operand is zero.
    DivisionByZero,
    /// A literal or intermediate result outside the range of `i64`.
    Overflow,
} || Allocator.Error;

const Operator = enum {
    add,
    sub,
    mul,
    div,
    rem,
    neg,
    /// Marks an open parenthesis; never applied.
    group,

    /// Binding strength; higher binds tighter. Binary operators are
    /// left-associative and `neg` is a prefix operator, so an operator on the
    /// stack is applied before pushing one of lower or equal precedence.
    fn precedence(op: Operator) u8 {
        return switch (op) {
            .group => 0,
            .add, .sub => 1,
            .mul, .div, .rem => 2,
            .neg => 3,
        };
    }
};

pub fn init(gpa: Allocator) Evaluator {
    return .{ .gpa = gpa };
}

pub fn deinit(e: *Evaluator) void {
    e.values.deinit(e.gpa);
    e.operators.deinit(e.gpa);
    e.* = undefined;
}

/// Returns the value of the expression in `line`, which must not contain the
/// line terminator. A line holding only blanks is a syntax error; callers
/// decide separately whether such lines produce output.
pub fn evaluate(e: *Evaluator, line: []const u8) Error!i64 {
    e.values.clearRetainingCapacity();
    e.operators.clearRetainingCapacity();

    // True where the grammar requires an operand: at the start, after an
    // operator and after `(`. False after a number or `)`.
    var expect_operand = true;
    var i: usize = 0;
    while (i < line.len) {
        const c = line[i];
        switch (c) {
            ' ', '\t' => i += 1,
            '0'...'9' => {
                if (!expect_operand) return error.Syntax;
                var value: i64 = 0;
                while (i < line.len and std.ascii.isDigit(line[i])) : (i += 1) {
                    value = try mul(value, 10);
                    value = try add(value, line[i] - '0');
                }
                try e.values.append(e.gpa, value);
                expect_operand = false;
            },
            '(' => {
                if (!expect_operand) return error.Syntax;
                try e.operators.append(e.gpa, .group);
                i += 1;
            },
            ')' => {
                if (expect_operand) return error.Syntax;
                try e.reduce(Operator.group.precedence() + 1);
                if (e.operators.pop() != .group) return error.Syntax;
                i += 1;
            },
            '-' => {
                if (expect_operand) {
                    try e.operators.append(e.gpa, .neg);
                } else {
                    try e.pushBinary(.sub);
                    expect_operand = true;
                }
                i += 1;
            },
            '+', '*', '/', '%' => {
                if (expect_operand) return error.Syntax;
                try e.pushBinary(switch (c) {
                    '+' => .add,
                    '*' => .mul,
                    '/' => .div,
                    '%' => .rem,
                    else => unreachable,
                });
                expect_operand = true;
                i += 1;
            },
            else => return error.Syntax,
        }
    }
    if (expect_operand) return error.Syntax;

    try e.reduce(Operator.group.precedence() + 1);
    if (e.operators.items.len != 0) return error.Syntax; // unclosed `(`
    std.debug.assert(e.values.items.len == 1);
    return e.values.items[0];
}

fn pushBinary(e: *Evaluator, op: Operator) Error!void {
    try e.reduce(op.precedence());
    try e.operators.append(e.gpa, op);
}

/// Applies stacked operators while their precedence is at least `min`.
/// Stops at an open parenthesis whenever `min` is above its precedence.
fn reduce(e: *Evaluator, min: u8) Error!void {
    while (e.operators.getLastOrNull()) |op| {
        if (op.precedence() < min) break;
        _ = e.operators.pop();
        try e.apply(op);
    }
}

/// Pops the operands of `op` from the value stack and pushes its result.
/// The operator/operand alternation enforced by `evaluate` guarantees the
/// operands are present.
fn apply(e: *Evaluator, op: Operator) Error!void {
    const values = &e.values.items;
    if (op == .neg) {
        const top = &values.*[values.len - 1];
        top.* = try sub(0, top.*);
        return;
    }
    const rhs = e.values.pop().?;
    const lhs = &values.*[values.len - 1];
    lhs.* = switch (op) {
        .add => try add(lhs.*, rhs),
        .sub => try sub(lhs.*, rhs),
        .mul => try mul(lhs.*, rhs),
        .div => try div(lhs.*, rhs),
        .rem => try rem(lhs.*, rhs),
        .neg, .group => unreachable,
    };
}

fn add(a: i64, b: i64) error{Overflow}!i64 {
    const r = @addWithOverflow(a, b);
    return if (r[1] != 0) error.Overflow else r[0];
}

fn sub(a: i64, b: i64) error{Overflow}!i64 {
    const r = @subWithOverflow(a, b);
    return if (r[1] != 0) error.Overflow else r[0];
}

fn mul(a: i64, b: i64) error{Overflow}!i64 {
    const r = @mulWithOverflow(a, b);
    return if (r[1] != 0) error.Overflow else r[0];
}

/// Division truncating toward zero.
fn div(a: i64, b: i64) error{ DivisionByZero, Overflow }!i64 {
    if (b == 0) return error.DivisionByZero;
    if (b == -1) return sub(0, a);
    return @divTrunc(a, b);
}

/// Remainder of truncating division: its sign follows the dividend.
fn rem(a: i64, b: i64) error{DivisionByZero}!i64 {
    if (b == 0) return error.DivisionByZero;
    // The quotient minInt / -1 overflows, but the remainder is exactly 0.
    if (b == -1) return 0;
    return @rem(a, b);
}

fn expectValue(expected: i64, line: []const u8) !void {
    var e: Evaluator = .init(std.testing.allocator);
    defer e.deinit();
    try std.testing.expectEqual(expected, try e.evaluate(line));
}

fn expectError(expected: Error, line: []const u8) !void {
    var e: Evaluator = .init(std.testing.allocator);
    defer e.deinit();
    try std.testing.expectError(expected, e.evaluate(line));
}

test "precedence and associativity" {
    try expectValue(7, "1 + 2 * 3");
    try expectValue(9, "(1 + 2) * 3");
    try expectValue(5, "1 + 2 * 3 - 4 / 2 % 3");
    try expectValue(70, "2*(3+4)*5");
    try expectValue(3, "10 - 4 - 3");
    try expectValue(2, "100 / 10 / 5");
    try expectValue(1, "17 % 10 % 3");
    try expectValue(42, "  \t42\t ");
    try expectValue(7, "007");
}

test "unary minus" {
    try expectValue(5, "--5");
    try expectValue(-6, "2 * -3");
    try expectValue(3, "1 - -2");
    try expectValue(-5, "-(2 + 3)");
    try expectValue(-6, "-2 * 3");
    try expectValue(-1, "- 7 % 3");
    try expectValue(-9223372036854775807, "-9223372036854775807");
}

test "division and remainder" {
    try expectValue(-3, "-7 / 2");
    try expectValue(-1, "-7 % 3");
    try expectValue(1, "7 % -3");
    try expectValue(0, "(-9223372036854775807 - 1) % -1");
    try expectValue(9223372036854775807, "9223372036854775807 / 1");
    try expectError(error.DivisionByZero, "1 / 0");
    try expectError(error.DivisionByZero, "5 % (2 - 2)");
}

test "overflow" {
    try expectError(error.Overflow, "9223372036854775808");
    try expectError(error.Overflow, "-9223372036854775808");
    try expectError(error.Overflow, "9223372036854775807 + 1");
    try expectError(error.Overflow, "-9223372036854775807 - 2");
    try expectError(error.Overflow, "(-9223372036854775807 - 1) / -1");
    try expectError(error.Overflow, "-(-9223372036854775807 - 1)");
    try expectError(error.Overflow, "4611686018427387904 * 2");
    try expectValue(-9223372036854775807 - 1, "-4611686018427387904 * 2");
}

test "syntax errors" {
    for ([_][]const u8{
        "", "   ", "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)",
        ")(", "1 (2)", "(1) 2", "1 * * 2", "1 -", "-", "1\r", "2 ** 3",
    }) |line| try expectError(error.Syntax, line);
}

test "deep nesting does not recurse" {
    const depth = 100_000;
    const line = try std.testing.allocator.alloc(u8, 2 * depth + 1);
    defer std.testing.allocator.free(line);
    @memset(line[0..depth], '(');
    line[depth] = '1';
    @memset(line[depth + 1 ..], ')');
    try expectValue(1, line);

    @memset(line[0 .. 2 * depth], '-');
    line[2 * depth] = '3';
    try expectValue(3, line);
}

//! `app calc`: see the "calc" section of SPEC.md.
//!
//! This module is owned by the calc subcommand. Additional files belong in
//! `src/calc/` and are imported from here.

const std = @import("std");
const Io = std.Io;
const Evaluator = @import("Evaluator.zig");

/// Runs the subcommand: reads standard input, writes standard output.
pub fn run(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    var stdin_buffer: [64 * 1024]u8 = undefined;
    var stdin_reader = Io.File.stdin().readerStreaming(io, &stdin_buffer);
    const input = try stdin_reader.interface.allocRemaining(gpa, .unlimited);
    defer gpa.free(input);

    var stdout_buffer: [64 * 1024]u8 = undefined;
    var stdout_writer = Io.File.stdout().writerStreaming(io, &stdout_buffer);
    const out = &stdout_writer.interface;

    var evaluator: Evaluator = .init(gpa);
    defer evaluator.deinit();

    try evaluateLines(&evaluator, input, out);
    try out.flush();
}

/// Writes one output line per non-blank line of `input`: the value of its
/// expression, or `error`.
fn evaluateLines(evaluator: *Evaluator, input: []const u8, out: *Io.Writer) !void {
    var lines = std.mem.splitScalar(u8, input, '\n');
    while (lines.next()) |line| {
        if (std.mem.trim(u8, line, " \t").len == 0) continue;
        if (evaluator.evaluate(line)) |value| {
            try out.print("{d}\n", .{value});
        } else |err| switch (err) {
            error.OutOfMemory => return err,
            error.Syntax, error.DivisionByZero, error.Overflow => try out.writeAll("error\n"),
        }
    }
}

test {
    _ = Evaluator;
}

test evaluateLines {
    var evaluator: Evaluator = .init(std.testing.allocator);
    defer evaluator.deinit();
    var out: Io.Writer.Allocating = .init(std.testing.allocator);
    defer out.deinit();

    try evaluateLines(&evaluator, "1 + 2 * 3\n-7 / 2\n\n \t\n(1 + 2\n9223372036854775807 + 1\n2", &out.writer);
    try std.testing.expectEqualStrings("7\n-3\nerror\nerror\n2\n", out.written());
}

//! A fixed-capacity LRU cache mapping short byte-string keys to short
//! byte-string values, with O(1) expected time per operation.
//!
//! Entries live in a growable array of nodes, linked into a doubly linked
//! recency list by index (head = most recently used). A hash set of node
//! indices, hashed and compared through the keys stored in the nodes, maps a
//! key to its node without storing the key twice. Slots freed by `del` are
//! kept on a free list and reused; once the cache is full, the least recently
//! used node is recycled in place for the new entry.

const std = @import("std");
const Allocator = std.mem.Allocator;
const assert = std.debug.assert;

const Cache = @This();

/// Maximum length in bytes of a key or a value.
pub const max_len = 64;

/// Maximum supported capacity; node indices must fit in `Index` with `nil`
/// left over as a sentinel.
pub const max_capacity = std.math.maxInt(Index) - 1;

const Index = u32;
const nil: Index = std.math.maxInt(Index);

const Node = struct {
    prev: Index,
    next: Index,
    key_len: u8,
    value_len: u8,
    key_buf: [max_len]u8,
    value_buf: [max_len]u8,

    fn key(node: *const Node) []const u8 {
        return node.key_buf[0..node.key_len];
    }

    fn value(node: *const Node) []const u8 {
        return node.value_buf[0..node.value_len];
    }

    fn setKey(node: *Node, k: []const u8) void {
        assert(k.len <= max_len);
        @memcpy(node.key_buf[0..k.len], k);
        node.key_len = @intCast(k.len);
    }

    fn setValue(node: *Node, v: []const u8) void {
        assert(v.len <= max_len);
        @memcpy(node.value_buf[0..v.len], v);
        node.value_len = @intCast(v.len);
    }
};

fn hashKey(key: []const u8) u32 {
    return @truncate(std.hash.Wyhash.hash(0, key));
}

/// Context for the index set: an index stands for the key of its node.
const IndexContext = struct {
    nodes: []const Node,

    pub fn hash(ctx: IndexContext, index: Index) u32 {
        return hashKey(ctx.nodes[index].key());
    }

    pub fn eql(_: IndexContext, a: Index, b: Index, _: usize) bool {
        // Keys in the set are unique, so equal keys mean equal indices.
        return a == b;
    }
};

/// Adapter for looking up the index set by key bytes.
const KeyAdapter = struct {
    nodes: []const Node,

    pub fn hash(_: KeyAdapter, key: []const u8) u32 {
        return hashKey(key);
    }

    pub fn eql(adapter: KeyAdapter, key: []const u8, index: Index, _: usize) bool {
        return std.mem.eql(u8, key, adapter.nodes[index].key());
    }
};

/// An array hash map rather than `std.HashMapUnmanaged`: its removals leave
/// no tombstones behind, so lookups stay fast under the constant
/// insert/evict churn of a full cache.
const IndexSet = std.ArrayHashMapUnmanaged(Index, void, IndexContext, true);

capacity: Index,
nodes: std.ArrayList(Node) = .empty,
index: IndexSet = .empty,
/// Most recently used entry.
head: Index = nil,
/// Least recently used entry.
tail: Index = nil,
/// Unused slots of `nodes`, chained through `Node.next`.
free_list: Index = nil,

/// Creates an empty cache holding at most `capacity` keys.
pub fn init(capacity: usize) Cache {
    assert(capacity >= 1 and capacity <= max_capacity);
    return .{ .capacity = @intCast(capacity) };
}

pub fn deinit(cache: *Cache, gpa: Allocator) void {
    cache.index.deinit(gpa);
    cache.nodes.deinit(gpa);
    cache.* = undefined;
}

/// Number of keys currently held.
pub fn count(cache: *const Cache) usize {
    return cache.index.count();
}

/// Returns the value stored for `key` and marks it most recently used.
/// The returned slice is valid until the next mutating call.
pub fn get(cache: *Cache, key: []const u8) ?[]const u8 {
    const i = cache.find(key) orelse return null;
    cache.moveToFront(i);
    return cache.nodes.items[i].value();
}

/// Inserts or overwrites `key`, marking it most recently used. Evicts the
/// least recently used key if the cache would exceed its capacity.
pub fn set(cache: *Cache, gpa: Allocator, key: []const u8, value: []const u8) Allocator.Error!void {
    assert(key.len <= max_len and value.len <= max_len);

    if (cache.find(key)) |i| {
        cache.nodes.items[i].setValue(value);
        cache.moveToFront(i);
        return;
    }

    // Reserve everything up front so that a failed allocation leaves the
    // cache unchanged.
    try cache.index.ensureUnusedCapacityContext(gpa, 1, cache.indexContext());
    const i = if (cache.count() == cache.capacity) cache.evict() else try cache.allocNode(gpa);

    const node = &cache.nodes.items[i];
    node.setKey(key);
    node.setValue(value);
    cache.linkFront(i);
    cache.index.putAssumeCapacityNoClobberContext(i, {}, cache.indexContext());
}

/// Removes `key`. Returns whether it was present.
pub fn del(cache: *Cache, key: []const u8) bool {
    const i = cache.find(key) orelse return false;
    cache.forget(i);
    cache.nodes.items[i].next = cache.free_list;
    cache.free_list = i;
    return true;
}

fn indexContext(cache: *const Cache) IndexContext {
    return .{ .nodes = cache.nodes.items };
}

fn find(cache: *const Cache, key: []const u8) ?Index {
    const ptr = cache.index.getKeyPtrAdapted(key, KeyAdapter{ .nodes = cache.nodes.items }) orelse return null;
    return ptr.*;
}

/// Returns an unused node slot, reusing a freed one if possible.
fn allocNode(cache: *Cache, gpa: Allocator) Allocator.Error!Index {
    if (cache.free_list != nil) {
        const i = cache.free_list;
        cache.free_list = cache.nodes.items[i].next;
        return i;
    }
    const i: Index = @intCast(cache.nodes.items.len);
    _ = try cache.nodes.addOne(gpa);
    return i;
}

/// Drops the least recently used entry and returns its now unused slot.
fn evict(cache: *Cache) Index {
    const i = cache.tail;
    assert(i != nil);
    cache.forget(i);
    return i;
}

/// Removes node `i` from both the index and the recency list.
fn forget(cache: *Cache, i: Index) void {
    // Must run while the node still holds its key: the index hashes it.
    const removed = cache.index.swapRemoveContext(i, cache.indexContext());
    assert(removed);
    cache.unlink(i);
}

fn unlink(cache: *Cache, i: Index) void {
    const nodes = cache.nodes.items;
    const node = &nodes[i];
    if (node.prev != nil) nodes[node.prev].next = node.next else cache.head = node.next;
    if (node.next != nil) nodes[node.next].prev = node.prev else cache.tail = node.prev;
}

fn linkFront(cache: *Cache, i: Index) void {
    const nodes = cache.nodes.items;
    nodes[i].prev = nil;
    nodes[i].next = cache.head;
    if (cache.head != nil) nodes[cache.head].prev = i else cache.tail = i;
    cache.head = i;
}

fn moveToFront(cache: *Cache, i: Index) void {
    if (cache.head == i) return;
    cache.unlink(i);
    cache.linkFront(i);
}

const testing = std.testing;

fn expectGet(cache: *Cache, key: []const u8, expected: ?[]const u8) !void {
    const actual = cache.get(key);
    if (expected) |e| {
        try testing.expect(actual != null);
        try testing.expectEqualStrings(e, actual.?);
    } else {
        try testing.expect(actual == null);
    }
}

test "evicts least recently used" {
    const gpa = testing.allocator;
    var cache: Cache = .init(2);
    defer cache.deinit(gpa);

    try cache.set(gpa, "a", "1");
    try cache.set(gpa, "b", "2");
    try expectGet(&cache, "a", "1");
    try cache.set(gpa, "c", "3");
    try expectGet(&cache, "b", null);
    try expectGet(&cache, "a", "1");
    try expectGet(&cache, "c", "3");
    try testing.expectEqual(2, cache.count());
}

test "overwrite refreshes recency" {
    const gpa = testing.allocator;
    var cache: Cache = .init(2);
    defer cache.deinit(gpa);

    try cache.set(gpa, "a", "1");
    try cache.set(gpa, "b", "2");
    try cache.set(gpa, "a", "a much longer value");
    try cache.set(gpa, "c", "3");
    try expectGet(&cache, "a", "a much longer value");
    try expectGet(&cache, "b", null);
    try expectGet(&cache, "c", "3");
}

test "del frees slots for reuse" {
    const gpa = testing.allocator;
    var cache: Cache = .init(3);
    defer cache.deinit(gpa);

    try cache.set(gpa, "x", "1");
    try testing.expect(cache.del("x"));
    try testing.expect(!cache.del("x"));
    try testing.expectEqual(0, cache.count());
    try expectGet(&cache, "x", null);

    for (0..3) |n| {
        var buf: [8]u8 = undefined;
        const k = try std.fmt.bufPrint(&buf, "k{d}", .{n});
        try cache.set(gpa, k, k);
    }
    try testing.expectEqual(3, cache.nodes.items.len);
    try testing.expect(cache.del("k1"));
    try cache.set(gpa, "k3", "v");
    try testing.expectEqual(3, cache.nodes.items.len);
    try testing.expectEqual(3, cache.count());
    try expectGet(&cache, "k0", "k0");
}

test "capacity one" {
    const gpa = testing.allocator;
    var cache: Cache = .init(1);
    defer cache.deinit(gpa);

    try cache.set(gpa, "a", "1");
    try cache.set(gpa, "b", "2");
    try expectGet(&cache, "a", null);
    try expectGet(&cache, "b", "2");
    try testing.expectEqual(1, cache.count());
    try testing.expect(cache.del("b"));
    try testing.expect(cache.head == nil and cache.tail == nil);
}

test "matches a naive model" {
    const gpa = testing.allocator;
    const capacity = 7;
    var cache: Cache = .init(capacity);
    defer cache.deinit(gpa);

    // Model: keys ordered from least to most recently used.
    var model_keys: [capacity + 1]u8 = undefined;
    var model_values: [capacity + 1]u8 = undefined;
    var model_len: usize = 0;

    var prng: std.Random.DefaultPrng = .init(42);
    const random = prng.random();
    for (0..20_000) |_| {
        const k = random.uintLessThan(u8, 20);
        const key: []const u8 = &.{'a' + k};
        const pos = std.mem.indexOfScalar(u8, model_keys[0..model_len], k);
        switch (random.uintLessThan(u8, 3)) {
            0 => {
                const v = random.int(u8);
                try cache.set(gpa, key, &.{v});
                if (pos) |p| {
                    std.mem.copyForwards(u8, model_keys[p .. model_len - 1], model_keys[p + 1 .. model_len]);
                    std.mem.copyForwards(u8, model_values[p .. model_len - 1], model_values[p + 1 .. model_len]);
                    model_len -= 1;
                }
                model_keys[model_len] = k;
                model_values[model_len] = v;
                model_len += 1;
                if (model_len > capacity) {
                    std.mem.copyForwards(u8, model_keys[0 .. model_len - 1], model_keys[1..model_len]);
                    std.mem.copyForwards(u8, model_values[0 .. model_len - 1], model_values[1..model_len]);
                    model_len -= 1;
                }
            },
            1 => {
                const got = cache.get(key);
                if (pos) |p| {
                    const v = model_values[p];
                    try testing.expectEqualSlices(u8, &.{v}, got.?);
                    std.mem.copyForwards(u8, model_keys[p .. model_len - 1], model_keys[p + 1 .. model_len]);
                    std.mem.copyForwards(u8, model_values[p .. model_len - 1], model_values[p + 1 .. model_len]);
                    model_keys[model_len - 1] = k;
                    model_values[model_len - 1] = v;
                } else {
                    try testing.expect(got == null);
                }
            },
            else => {
                try testing.expectEqual(pos != null, cache.del(key));
                if (pos) |p| {
                    std.mem.copyForwards(u8, model_keys[p .. model_len - 1], model_keys[p + 1 .. model_len]);
                    std.mem.copyForwards(u8, model_values[p .. model_len - 1], model_values[p + 1 .. model_len]);
                    model_len -= 1;
                }
            },
        }
        try testing.expectEqual(model_len, cache.count());
    }
}

//! `app lru`: see the "lru" section of SPEC.md.
//!
//! Reads a capacity line followed by one command per line from standard
//! input, applies the commands to an LRU cache and writes their results to
//! standard output, one per line.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Io = std.Io;

pub const Cache = @import("Cache.zig");

/// Runs the subcommand: reads standard input, writes standard output.
pub fn run(init: std.process.Init) !void {
    const io = init.io;

    var in_buf: [64 * 1024]u8 = undefined;
    var stdin = Io.File.stdin().readerStreaming(io, &in_buf);

    var out_buf: [64 * 1024]u8 = undefined;
    var stdout = Io.File.stdout().writerStreaming(io, &out_buf);

    try simulate(init.gpa, &stdin.interface, &stdout.interface);
    try stdout.interface.flush();
}

/// Reads the capacity and the commands from `in` and writes the outputs to
/// `out`. Lines that are not well-formed commands are ignored.
pub fn simulate(gpa: Allocator, in: *Io.Reader, out: *Io.Writer) !void {
    const first = try in.takeDelimiter('\n') orelse return;
    const capacity = std.fmt.parseUnsigned(usize, std.mem.trim(u8, first, " \t\r"), 10) catch return error.InvalidCapacity;
    if (capacity < 1 or capacity > Cache.max_capacity) return error.InvalidCapacity;

    var cache: Cache = .init(capacity);
    defer cache.deinit(gpa);

    while (try in.takeDelimiter('\n')) |line| {
        const command = Command.parse(trimLine(line)) orelse continue;
        switch (command) {
            .set => |args| try cache.set(gpa, args.key, args.value),
            .get => |key| try out.print("{s}\n", .{cache.get(key) orelse "NULL"}),
            .del => |key| try out.writeAll(if (cache.del(key)) "1\n" else "0\n"),
            .size => try out.print("{d}\n", .{cache.count()}),
        }
    }
}

/// Strips a trailing carriage return so CRLF input is accepted too.
fn trimLine(line: []const u8) []const u8 {
    return std.mem.trimEnd(u8, line, "\r");
}

const Command = union(enum) {
    set: struct { key: []const u8, value: []const u8 },
    get: []const u8,
    del: []const u8,
    size,

    /// Parses one command line, or returns null if it is malformed.
    fn parse(line: []const u8) ?Command {
        var tokens = std.mem.splitScalar(u8, line, ' ');
        const name = tokens.first();
        const command: Command = if (std.mem.eql(u8, name, "SET")) blk: {
            const key = token(&tokens) orelse return null;
            const value = token(&tokens) orelse return null;
            break :blk .{ .set = .{ .key = key, .value = value } };
        } else if (std.mem.eql(u8, name, "GET"))
            .{ .get = token(&tokens) orelse return null }
        else if (std.mem.eql(u8, name, "DEL"))
            .{ .del = token(&tokens) orelse return null }
        else if (std.mem.eql(u8, name, "SIZE"))
            .size
        else
            return null;
        if (tokens.next() != null) return null;
        return command;
    }

    fn token(tokens: *std.mem.SplitIterator(u8, .scalar)) ?[]const u8 {
        const t = tokens.next() orelse return null;
        if (t.len == 0 or t.len > Cache.max_len) return null;
        return t;
    }
};

fn expectOutput(input: []const u8, expected: []const u8) !void {
    var in: Io.Reader = .fixed(input);
    var out: Io.Writer.Allocating = .init(std.testing.allocator);
    defer out.deinit();
    try simulate(std.testing.allocator, &in, &out.writer);
    try std.testing.expectEqualStrings(expected, out.written());
}

test "spec example" {
    try expectOutput("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n", "1\nNULL\n2\n");
}

test "last line without newline" {
    try expectOutput("3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x", "1\n0\n0\nNULL\n");
}

test "crlf and malformed lines" {
    try expectOutput("1\r\nSET a 1\r\n\nBOGUS\nGET\nGET a b\nGET a\r\nSIZE", "1\n1\n");
}

test "empty input" {
    try expectOutput("", "");
}

test "invalid capacity" {
    var in: Io.Reader = .fixed("0\nSIZE\n");
    var out: Io.Writer.Allocating = .init(std.testing.allocator);
    defer out.deinit();
    try std.testing.expectError(error.InvalidCapacity, simulate(std.testing.allocator, &in, &out.writer));
}

test {
    _ = Cache;
}

//! Entry point of `app`: dispatches the first argument to a subcommand.

const std = @import("std");

const Subcommand = enum { wordfreq, lru, calc };

pub fn main(init: std.process.Init) !void {
    var args = init.minimal.args.iterate();
    _ = args.skip(); // program name

    const name = args.next() orelse usage();
    const subcommand = std.meta.stringToEnum(Subcommand, name) orelse usage();

    switch (subcommand) {
        .wordfreq => try @import("wordfreq").run(init),
        .lru => try @import("lru").run(init),
        .calc => try @import("calc").run(init),
    }
}

fn usage() noreturn {
    std.debug.print("usage: app <wordfreq|lru|calc>\n", .{});
    std.process.exit(2);
}

